# SaleHop update: first-visit welcome carousel
# - Adds a short, one-time welcome overlay for new visitors: a 4-slide
#   carousel explaining what SaleHop does -- two slides for buyers
#   (browse/map nearby sales, favorite to build a one-tap driving route)
#   and two for sellers (post a sale free, print a matching yard sign +
#   QR code). Shown once ever per browser, then never again on its own --
#   dismissible immediately with "Skip" at any point.
# - Reachable again anytime via a small "?" button next to "Your Account"
#   on the Account screen (both signed-in and signed-out views), for
#   anyone who dismissed it too fast or wants a refresher.
# - New file: components/WelcomeOverlay.js. Touches components/AppShell.js
#   (shows/dismisses it, tracks the "seen it" flag in localStorage under
#   salehop:onboardingSeen -- same pattern already used for favorites),
#   components/AccountScreen.js (the "?" button), and app/globals.css (the
#   overlay's styling, matching the existing brand colors/fonts). No
#   database changes, no new npm package.

if (-not (Test-Path "package.json")) {
    Write-Host "ERROR: package.json not found. Run this script from inside your salehop project folder." -ForegroundColor Red
    exit 1
}
if (-not (Test-Path ".git")) {
    Write-Host "ERROR: .git folder not found. Run this script from inside your salehop project folder." -ForegroundColor Red
    exit 1
}

[System.IO.Directory]::SetCurrentDirectory((Get-Location).Path)

$dir_welcomeoverlay = "components"
[System.IO.Directory]::CreateDirectory($dir_welcomeoverlay) | Out-Null
